const feedType=cam=>cam?.stream?'live':cam?.videoClip?'clip':'image';
const feedTypeName=cam=>({live:'Live video',clip:'Video clips',image:'Refreshing images'})[feedType(cam)];
const feedPicker=document.createElement('dialog');feedPicker.id='feed-picker';feedPicker.innerHTML='<div class="dialog-head"><span class="eyebrow">MISSION SOURCE / CHOOSE A CAMERA</span><button class="close" aria-label="Close camera picker">×</button></div><h2>Give your agent a place to watch</h2><p>Find a location, preview its camera, and choose the source for your mission</p><div class="feed-picker-filters"><input type="search" id="feed-search" placeholder="Search location, road or country" aria-label="Search mission cameras"><select id="feed-provider" aria-label="Filter mission camera provider"><option value="all">All providers</option></select><select id="feed-type" aria-label="Filter camera media type"><option value="all">All feed types</option><option value="live">Live video only</option><option value="clip">Video clips</option><option value="image">Refreshing images</option></select></div><div class="feed-picker-layout"><div><span id="feed-result-count"></span><div id="feed-results"></div><button class="button small" id="feed-more">Show more cameras</button></div><aside id="feed-inspect"><div class="feed-empty">Select a camera to preview its source</div></aside></div>';
document.body.append(feedPicker);let feedPickerForm=null,feedSelection=null,feedPreviewPlayer=null,feedLimit=24,feedData=[];
feedPicker.querySelector('.close').onclick=()=>feedPicker.close();feedPicker.addEventListener('close',()=>{feedPreviewPlayer?.destroy();feedPreviewPlayer=null;});
function installCameraOnForm(form,camera){
  if(!form?.isConnected)return;form.selectedCamera=camera;form.querySelector('[name="cameraId"]').value=camera.id;
  const region=form.elements.region;if(![...region.options].some(o=>o.value===camera.region))region.add(new Option(camera.city,camera.region));region.value=camera.region;
  form.elements.cameras.value='1';const freq=form.elements.interval,minimum=Math.max(1,Math.ceil(camera.interval/60)),selected=Number(freq.value);freq.innerHTML=[...new Set([minimum,5,10,15,30,60].filter(v=>v>=minimum))].sort((a,b)=>a-b).map(v=>'<option value="'+v+'">Every '+v+' minutes</option>').join('');freq.value=String([...freq.options].some(o=>Number(o.value)===selected)?selected:minimum);
  form.querySelector('#selected-camera').innerHTML='<span class="selected-camera-glyph">▧</span><span><b>'+escapeHtml(camera.name)+'</b><small>'+escapeHtml(camera.city)+' · '+escapeHtml(camera.provider)+'</small><em>'+feedTypeName(camera)+'</em></span><span class="change-model">Change</span>';
  form.querySelector('#camera-fit-note').textContent=feedType(camera)==='live'?'Continuous video for viewing · AI analyzes provider snapshots about every '+minimum+' minutes':feedType(camera)==='clip'?'Short source clips refresh periodically · AI analyzes provider snapshots about every '+minimum+' minutes':'Source images refresh about every '+minimum+' minutes · Continuous video is not supplied by this API';
  form.dispatchEvent(new Event('input',{bubbles:true}));
}
window.initLaunchCamera=(form,seed)=>{
  const block=document.createElement('div');block.className='launch-camera-section';block.innerHTML='<label class="launch-model-label">Camera source <span>One camera per mission</span></label><button type="button" id="selected-camera" class="selected-model" aria-haspopup="dialog"><span class="selected-camera-glyph">▧</span><span><b>Choose a camera</b><small>Search the connected source directory</small></span><span class="change-model">Browse</span></button><input type="hidden" name="cameraId"><div id="camera-fit-note">Select the exact camera your agent should observe</div>';form.prepend(block);
  form.elements.region.closest('label').hidden=true;form.elements.cameras.closest('label').hidden=true;form.elements.cameras.value='1';
  form.querySelector('#selected-camera').onclick=()=>showFeedPicker(form);
  const list=cameraDirectory.data.length?cameraDirectory.data:liveState.cameras;const camera=list.find(c=>c.id===seed?.cameraId)||list.find(c=>c.region===(seed?.region||selectedRegion));if(camera)installCameraOnForm(form,camera);
};
window.validateLaunchCamera=form=>{if(!form.selectedCamera){document.querySelector('#form-error').textContent='Choose a camera source before saving this mission';return false;}return true;};
const modelAndCameraMetadata=window.draftModelMetadata;window.draftModelMetadata=form=>{const camera=form.selectedCamera;return {...modelAndCameraMetadata(form),...(camera?{cameraId:camera.id,cameraName:camera.name,cameraProvider:camera.provider,region:camera.region,cameras:1,feedType:feedType(camera),sourceUrl:camera.source,sourceRefreshSeconds:camera.interval}:{})};};
async function showFeedPicker(form){
  feedPickerForm=form;feedSelection=form.selectedCamera;feedLimit=24;feedData=cameraDirectory.data.length?cameraDirectory.data:liveState.cameras;
  feedPicker.showModal();document.querySelector('#feed-search').value='';document.querySelector('#feed-type').value='all';document.querySelector('#feed-provider').innerHTML='<option value="all">All providers</option>'+[...new Set(feedData.map(c=>c.provider))].map(p=>'<option>'+escapeHtml(p)+'</option>').join('');renderFeedResults();if(feedSelection)inspectFeed(feedSelection);else document.querySelector('#feed-inspect').innerHTML='<div class="feed-empty">Select a camera to preview its source</div>';
  if(feedData.length<10){try{const r=await fetch('/api/camera-catalog');if(!r.ok)throw new Error();const payload=await r.json();if(!feedPicker.open)return;feedData=payload.data;document.querySelector('#feed-provider').innerHTML='<option value="all">All providers</option>'+[...new Set(feedData.map(c=>c.provider))].map(p=>'<option>'+escapeHtml(p)+'</option>').join('');renderFeedResults();}catch{document.querySelector('#feed-result-count').textContent='Showing the available featured cameras';}}
}
function renderFeedResults(){
  const query=document.querySelector('#feed-search').value.toLowerCase().trim(),provider=document.querySelector('#feed-provider').value,type=document.querySelector('#feed-type').value;
  const list=feedData.filter(c=>(provider==='all'||c.provider===provider)&&(type==='all'||feedType(c)===type)&&(!query||[c.name,c.city,c.region,c.provider].join(' ').toLowerCase().includes(query)));
  document.querySelector('#feed-result-count').textContent=list.length.toLocaleString()+' cameras · preview availability before choosing';document.querySelector('#feed-results').innerHTML=list.length?list.slice(0,feedLimit).map(c=>'<button class="feed-result '+(feedSelection?.id===c.id?'selected':'')+'" data-feed-id="'+escapeHtml(c.id)+'"><span class="feed-result-icon">'+(c.stream?'▷':'▧')+'</span><span><b>'+escapeHtml(c.name)+'</b><small>'+escapeHtml(c.city)+' · '+escapeHtml(c.provider)+'</small><em>'+feedTypeName(c)+' · '+c.interval/60+' min AI source interval</em></span><span>↗</span></button>').join(''):'<div class="feed-empty">No cameras match these filters</div>';document.querySelector('#feed-more').hidden=list.length<=feedLimit;document.querySelectorAll('[data-feed-id]').forEach(b=>b.onclick=()=>inspectFeed(feedData.find(c=>c.id===b.dataset.feedId)));
}
function inspectFeed(camera){feedSelection=camera;feedPreviewPlayer?.destroy();const area=document.querySelector('#feed-inspect');area.innerHTML='<div id="feed-preview-player"></div><div class="feed-preview-description"><span class="feed-type-badge">'+feedTypeName(camera)+'</span><h3>'+escapeHtml(camera.name)+'</h3><p>'+escapeHtml(camera.city)+'</p><dl><div><dt>Source</dt><dd>'+escapeHtml(camera.provider)+'</dd></div><div><dt>AI image cadence</dt><dd>About '+camera.interval/60+' minutes</dd></div></dl><p class="feed-source-note">'+(feedType(camera)==='live'?'Video plays continuously while available The AI currently samples the provider’s still images':feedType(camera)==='clip'?'This is a repeating short clip, not continuous live video The latest clip is fetched at the source interval':'This source supplies refreshing images Continuous live video is not available through this API')+'</p><button class="button primary" id="use-camera-source">Use this camera ↗</button><a href="'+escapeHtml(camera.source)+'" target="_blank" rel="noopener">Official camera source ↗</a></div>';feedPreviewPlayer=createCameraPlayer(document.querySelector('#feed-preview-player'),camera);document.querySelector('#use-camera-source').onclick=()=>{installCameraOnForm(feedPickerForm,camera);feedPicker.close();};document.querySelectorAll('[data-feed-id]').forEach(b=>b.classList.toggle('selected',b.dataset.feedId===camera.id));}
for(const id of ['feed-search','feed-provider','feed-type'])document.querySelector('#'+id).addEventListener(id==='feed-search'?'input':'change',()=>{feedLimit=24;renderFeedResults();});document.querySelector('#feed-more').onclick=()=>{feedLimit+=24;renderFeedResults();};
